/**
 * A pasted image, stored for the agent to open with Read (#werk-shots). The bytes go to a
 * file in .werk/attachments, named by a timestamp and a random id. The folder ignores itself
 * in git: a screenshot is transcript, not map.
 */
import { randomBytes } from 'node:crypto'
import { existsSync, mkdirSync, writeFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'

const EXTENSIONS: Record<string, string> = { 'image/png': 'png', 'image/jpeg': 'jpg', 'image/gif': 'gif', 'image/webp': 'webp' }
export const IMAGE_LIMIT_BYTES = 20 * 1024 * 1024

export type PastedImage = { type: string; data: string }

export const attachmentsDir = (logPath: string) => resolve(dirname(logPath), 'attachments')

/** Why the image cannot be stored, or null when it can. */
export function imageProblem(image: unknown): string | null {
  const { type, data } = (image ?? {}) as Record<string, unknown>
  if (typeof type !== 'string' || !(type in EXTENSIONS)) return `an image must be one of ${Object.keys(EXTENSIONS).join(', ')}`
  if (typeof data !== 'string' || !/^[A-Za-z0-9+/]*={0,2}$/.test(data)) return 'an image needs its bytes in base64'
  if ((data.length * 3) / 4 > IMAGE_LIMIT_BYTES) return 'an image is larger than 20 MB'
  return null
}

/** Writes the image and returns its absolute path. */
export function storeImage(logPath: string, image: PastedImage): string {
  const dir = attachmentsDir(logPath)
  mkdirSync(dir, { recursive: true })
  const ignore = join(dir, '.gitignore')
  if (!existsSync(ignore)) writeFileSync(ignore, '*\n')
  const stamp = new Date().toISOString().replace(/[:.]/g, '-')
  const path = join(dir, `${stamp}-${randomBytes(4).toString('hex')}.${EXTENSIONS[image.type]}`)
  writeFileSync(path, Buffer.from(image.data, 'base64'))
  return path
}
